var TIPS = ["Tap a squad bonus chip in battle to see exactly what it does.","Matching traits unlock squad bonuses: two Jedi, two Rebels, three Droids\u2026","Every world has its own terrain and hazard. Check the datapad before you fight.","Duplicate cards become shards. Collect enough to add a Star.","The gold bar under a card is its Ultimate. It fills as you deal and take hits.","Claim the daily reward in the Black Market. The streak keeps getting better.","Tap any card in your collection, then its Ultimate page, to watch the move.","The Endless Tower gets harder every floor, and pays more too.","Speed decides who moves first. Watch the turn order strip at the top."];
function fit(ls) { var w = ls.clientWidth, h = ls.clientHeight; var k = w / h > 0.8 ? Math.min(w / 390, h / 844) : Math.max(w / 390, h / 844); ls.querySelector('.stage').style.setProperty('--k', k); }
